"use client";
import type { AdminProperty } from "@/lib/admin/schema";
import { amenitySchema } from "@/lib/property-validation";
import { Field } from "./Fields";
export default function AmenitiesEditor({ data, change, errors }: { data: AdminProperty; change: (data: AdminProperty) => void; errors: Record<string, string> }) {
  const update = (index: number, patch: Partial<AdminProperty["amenities"][number]>) => change({ ...data, amenities: data.amenities.map((a, i) => i === index ? { ...a, ...patch } : a) });
  return <section className="admin-card"><p className="admin-eyebrow">05 / Beyond the residence</p><div className="admin-section-heading"><div><h2>A life well appointed</h2><p>The services and spaces that make this address exceptional.</p></div><button className="admin-secondary" disabled={data.amenities.length >= 30} onClick={() => change({ ...data, amenities: [...data.amenities, { icon: "Waves", title: "New amenity", text: "" }] })}>+ Add amenity</button></div>
    {!data.amenities.length && <p className="admin-empty">Add amenities to tell the full story.</p>}{data.amenities.map((a, index) => <fieldset className="admin-nested" key={index}><legend>Amenity {index + 1}</legend><div className="admin-form-grid"><Field label="Amenity title" value={a.title} error={errors[`amenities.${index}.title`]} onChange={(e) => update(index, { title: e.target.value })} /><label className="admin-field"><span>Icon</span><select value={a.icon} onChange={(e) => update(index, { icon: amenitySchema.shape.icon.parse(e.target.value) })}>{amenitySchema.shape.icon.options.map((icon) => <option key={icon} value={icon}>{({ Waves: "Pool", Dumbbell: "Fitness", Wine: "Lounge", BellRing: "Concierge", Clapperboard: "Cinema", Flower2: "Wellness" })[icon]}</option>)}</select></label><Field label="Amenity description" multiline value={a.text} maxLength={1000} error={errors[`amenities.${index}.text`]} onChange={(e) => update(index, { text: e.target.value })} /></div><button className="admin-danger-link" onClick={() => { if (window.confirm(`Remove ${a.title}?`)) change({ ...data, amenities: data.amenities.filter((_, i) => i !== index) }); }}>Remove amenity</button></fieldset>)}
  </section>;
}
